const MIN_PHOTO_WIDTH=1080;
// iPhone сохраняет видео в контейнере QuickTime (.MOV, video/quicktime). Это тот же формат ISO (блок ftyp), что и MP4:
// площадки его принимают, поэтому файл передаётся дальше как MP4 без перекодирования.
function normalizeVideo(w,file){if(file&&(file.type==='video/quicktime'||(!file.type&&/\.mov$/i.test(file.name||'')))){try{return new w.File([file],String(file.name||'video').replace(/\.mov$/i,'')+'.mp4',{type:'video/mp4',lastModified:file.lastModified});}catch{return file;}}return file;}
